def cells_connected_to_border(grid, start_pos):
    rows, cols = len(grid), len(grid[0])
    start = start_pos
    visited = set()
    queue = deque()

    if 0 <= start[0] < rows and 0 <= start[1] < cols:
        queue.append(start)
        visited.add(start)

    while queue:
        r, c = queue.popleft()
        if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:
            return True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0 and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))
    return False

